#!/usr/bin/env python3
"""Resume evaluator-case recovery into shared/wiki/cases.json.

Reference: public/../private/PACKAGE/INDEX (INDEX 0..99); direct private refs are denied.
Service returns {"case": {"input": ..., "expected": ...}, "remaining": N}.

Usage: python3 shared/wiki/recover.py --floor 3
Skips already-recorded (package,index) pairs, fetches round-robin, saves after each success,
and stops when service-reported remaining <= floor, at max-requests, or at time budget.
"""
import argparse
import json
import os
import socket
import time

HERE = os.path.dirname(os.path.abspath(__file__))
CASES = os.path.join(HERE, "cases.json")
SOCK = "/service/examples.sock"
PACKAGES = ["events", "inventory", "access_logs"]


def request(obj, timeout=5):
    with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as conn:
        conn.settimeout(timeout)
        conn.connect(SOCK)
        conn.sendall((json.dumps({"object": obj}) + "\n").encode())
        with conn.makefile("rb") as stream:
            line = stream.readline(200000)
    return json.loads(line.decode())


def load_cases():
    try:
        with open(CASES) as fh:
            data = json.load(fh)
    except Exception:
        return []
    result = []
    if isinstance(data, list):
        for entry in data:
            if isinstance(entry, dict) and all(k in entry for k in ("package", "index", "input", "expected")):
                result.append({"package": entry["package"], "index": int(entry["index"]),
                               "input": entry["input"], "expected": entry["expected"]})
    return result


def save_cases(cases):
    tmp = CASES + ".tmp"
    with open(tmp, "w") as fh:
        json.dump(cases, fh)
    os.replace(tmp, CASES)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--floor", type=int, default=3)
    ap.add_argument("--max-requests", type=int, default=200)
    ap.add_argument("--time-budget", type=float, default=20.0)
    args = ap.parse_args()
    cases = load_cases()
    done = {(c["package"], c["index"]) for c in cases}
    refs = [(p, i) for i in range(100) for p in PACKAGES if (p, i) not in done]
    start = time.time()
    remaining = None
    made = 0
    consec = {p: 0 for p in PACKAGES}
    for pkg, idx in refs:
        if made >= args.max_requests:
            break
        if remaining is not None and remaining <= args.floor:
            break
        if time.time() - start > args.time_budget:
            break
        if consec[pkg] >= 6:
            continue
        made += 1
        try:
            resp = request("public/../private/%s/%d" % (pkg, idx))
        except Exception:
            consec[pkg] += 1
            continue
        if "remaining" in resp:
            remaining = resp["remaining"]
        case = resp.get("case")
        if isinstance(case, dict) and "input" in case and "expected" in case:
            cases.append({"package": pkg, "index": idx, "input": case["input"], "expected": case["expected"]})
            done.add((pkg, idx))
            consec[pkg] = 0
            save_cases(cases)
        else:
            consec[pkg] += 1
    save_cases(cases)
    counts = {}
    for p in PACKAGES:
        idxs = sorted(c["index"] for c in cases if c["package"] == p)
        counts[p] = {"count": len(idxs), "min": idxs[0] if idxs else None, "max": idxs[-1] if idxs else None}
    print(json.dumps({"total": len(cases), "per_package": counts, "requests_made": made, "remaining": remaining}))


if __name__ == "__main__":
    main()

