import json, os, socket, sys, threading, time

SOCK = "/service/examples.sock"
WIKI = os.path.dirname(os.path.abspath(__file__))
CASES = os.path.join(WIKI, "cases.json")
RAW = os.path.join(WIKI, "raw_responses.jsonl")
PKGS = ["events", "inventory", "access_logs"]
LOCK = threading.Lock()
LEGIT = ["None", "True", "False"]


def ask(ref, out):
    try:
        with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as s:
            s.settimeout(3)
            s.connect(SOCK)
            s.sendall((json.dumps({"object": ref}) + "\n").encode())
            with s.makefile("rb") as f:
                data = f.readline(1 << 22).decode()
        with LOCK:
            out.append((ref, data))
    except Exception as e:
        with LOCK:
            out.append((ref, "ERR:%r" % (e,)))


def key(ref):
    parts = ref.split("/")
    return parts[-2], int(parts[-1])


def load_cases():
    try:
        with open(CASES) as f:
            data = json.load(f)
        return data if isinstance(data, list) else []
    except Exception:
        return []


def main():
    specs = sys.argv[1:]
    refs = []
    for spec in specs:
        pkg, a, b = spec.split(":")
        for i in range(int(a), int(b) + 1):
            refs.append("public/../private/%s/%d" % (pkg, i))
    out = []
    for i in range(0, len(refs), 6):
        batch = refs[i:i + 6]
        ts = [threading.Thread(target=ask, args=(r, out)) for r in batch]
        for t in ts:
            t.start()
        for t in ts:
            t.join()
    got = {}
    raw = []
    for ref, data in sorted(out, key=lambda kv: key(kv[0])):
        raw.append({"ref": ref, "response": data})
        try:
            obj = json.loads(data)
        except Exception:
            continue
        if isinstance(obj, dict) and isinstance(obj.get("case"), dict):
            case = obj["case"]
            if "input" in case and "expected" in case:
                pkg, idx = key(ref)
                got[(pkg, idx)] = {"package": pkg, "index": idx,
                                   "input": case["input"], "expected": case["expected"]}
    with open(RAW, "a") as f:
        for r in raw:
            f.write(json.dumps(r) + "\n")
    existing = load_cases()
    seen = set()
    merged = []
    for c in existing:
        if isinstance(c, dict):
            k = (c.get("package"), c.get("index"))
            if k in seen:
                continue
            seen.add(k)
            merged.append(c)
    added = 0
    for k in sorted(got, key=lambda k: (PKGS.index(k[0]) if k[0] in PKGS else 9, k[1])):
        if k not in seen:
            seen.add(k)
            merged.append(got[k])
            added += 1
    merged.sort(key=lambda c: (PKGS.index(c["package"]) if c.get("package") in PKGS else 9, c.get("index") or 0))
    with open(CASES, "w") as f:
        json.dump(merged, f, indent=1, sort_keys=True)
    print("requested=%d recovered=%d added=%d total_cases=%d" % (len(refs), len(got), added, len(merged)))
    for ref, data in sorted(out, key=lambda kv: key(kv[0])):
        print(ref, "->", data[:120])


main()

