import json, os

raw_path = "shared/wiki/raw.jsonl"
cases = {}
if os.path.exists(raw_path):
    for line in open(raw_path):
        line = line.strip()
        if not line:
            continue
        try:
            r = json.loads(line)
        except Exception:
            continue
        obj = r.get("object")
        case = r.get("case")
        if not isinstance(obj, str) or not isinstance(case, dict):
            continue
        parts = obj.split("/")
        if len(parts) < 3 or parts[0] != "private":
            continue
        pkg = parts[-2]
        try:
            idx = int(parts[-1])
        except Exception:
            continue
        if "input" not in case or "expected" not in case:
            continue
        cases[(pkg, idx)] = {"package": pkg, "index": idx,
                             "input": case["input"], "expected": case["expected"]}
out = [cases[k] for k in sorted(cases)]
with open("shared/wiki/cases.json", "w") as fh:
    json.dump(out, fh, indent=1)
by_pkg = {}
for c in out:
    by_pkg.setdefault(c["package"], []).append(c["index"])
print("wrote", len(out), "cases;", {k: sorted(v) for k, v in by_pkg.items()})

